def merge_ranges(ranges):
    # Filter out empty ranges and create a sorted list of valid ranges
    valid = []
    for r in ranges:
        start, end = r
        if start < end:  # discard empty or invalid ranges
            valid.append((start, end))
    # Sort by start value
    valid.sort(key=lambda x: x[0])
    merged = []
    for r in valid:
        if not merged:
            merged.append([r[0], r[1]])
        else:
            last = merged[-1]
            # If current range overlaps or touches the last merged range, merge them
            if r[0] <= last[1]:
                last[1] = max(last[1], r[1])
            else:
                merged.append([r[0], r[1]])
    # Convert back to tuples
    return [tuple(item) for item in merged]

import heapq
from collections import defaultdict
def topological(edges, nodes):
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        adj[u].append(v)
        indegree[v] += 1
        if u not in indegree:
            indegree[u] = 0
    # Initialize heap with nodes having indegree 0
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result

def decode_runs(text):
    if text == "":
        return ""
    i = 0
    n = len(text)
    result = []
    while i < n:
        # Parse the count (must be decimal positive integer)
        if i >= n or not ('0' <= text[i] <= '9'):
            raise ValueError
        count_digits = []
        while i < n and '0' <= text[i] <= '9':
            count_digits.append(text[i])
            i += 1
        if not count_digits:
            raise ValueError
        count = int(''.join(count_digits))
        if count <= 0:
            raise ValueError
        # Parse the letter (must be lowercase ASCII)
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError
        letter = text[i]
        i += 1
        result.append(letter * count)
    return ''.join(result)

from collections import OrderedDict
def lru(capacity, operations):
    cache = OrderedDict()
    results = []
    if capacity == 0:
        for op in operations:
            if op[0] == "get":
                results.append(-1)
        return results
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.move_to_end(key)
                cache[key] = value
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value
                cache.move_to_end(key)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

def shortest(graph, start, end):
    if start == end:
        return 0
    import heapq
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist.get(u, None):
            continue
        if u == end:
            return d
        for v, w in graph.get(u, []):
            nd = d + w
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return None

def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    n = len(values)
    if k > n:
        return []
    from collections import deque
    dq = deque()  # stores indices, values are decreasing
    result = []
    for i in range(n):
        # Remove indices that are out of the current window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove indices whose values are less than the current value
        while dq and values[dq[-1]] < values[i]:
            dq.pop()
        dq.append(i)
        # Start recording results once the first window is complete
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

import copy
def deep_merge(left, right):
    if isinstance(left, dict) and isinstance(right, dict):
        merged = copy.deepcopy(left)
        for key, val in right.items():
            if key in merged:
                if isinstance(merged[key], dict) and isinstance(val, dict):
                    merged[key] = deep_merge(merged[key], val)
                else:
                    merged[key] = copy.deepcopy(val)
            else:
                merged[key] = copy.deepcopy(val)
        return merged
    else:
        # If not both dictionaries, return a deep copy of right if provided, else left
        if right is not None:
            return copy.deepcopy(right)
        else:
            return copy.deepcopy(left)

def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    buckets = {}
    result = []
    for t, key in events:
        bucket = buckets.get(key, [])
        # Remove timestamps outside the window (t - window, exclusive)
        bucket = [ts for ts in bucket if ts > t - window]
        buckets[key] = bucket
        if len(bucket) < limit:
            bucket.append(t)
            buckets[key] = bucket
            result.append(True)
        else:
            result.append(False)
    return result

def json_pointer(value, pointer):
    if pointer == "":
        return value
    # Unescape the pointer
    unescaped_chars = []
    i = 0
    while i < len(pointer):
        if pointer[i] == '~':
            if i + 1 >= len(pointer):
                raise ValueError("Malformed escape")
            next_char = pointer[i+1]
            if next_char == '0':
                unescaped_chars.append('~')
                i += 2
            elif next_char == '1':
                unescaped_chars.append('/')
                i += 2
            else:
                raise ValueError("Malformed escape")
        else:
            unescaped_chars.append(pointer[i])
            i += 1
    unescaped = ''.join(unescaped_chars)
    # Split into tokens
    tokens = unescaped.split('/')
    current = value
    for token in tokens:
        if token == '':
            continue
        if isinstance(current, dict):
            if token not in current:
                raise ValueError("Missing path")
            current = current[token]
        elif isinstance(current, list):
            if not token.isdigit():
                raise ValueError("Invalid list index")
            if token[0] == '0' and len(token) > 1:
                raise ValueError("Invalid list index")
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise ValueError("Missing path")
            current = current[idx]
        else:
            raise ValueError("Invalid path")
    return current

def stable_unique(values):
    seen = []
    result = []
    for v in values:
        if v not in seen:
            seen.append(v)
            result.append(v)
    return result

def apply_patch(text, edits):
    # Validate edits list
    if not isinstance(edits, list):
        edits = []
    # Check each edit for basic structure and range
    starts = set()
    for edit in edits:
        if not (isinstance(edit, tuple) and len(edit) == 3):
            raise ValueError("Each edit must be a tuple (start, end, replacement)")
        start, end, replacement = edit
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Start and end must be integers")
        if start < 0 or end < 0 or start > end:
            raise ValueError("Invalid start or end offset")
        if end > len(text):
            raise ValueError("End offset out of range")
        if start in starts:
            raise ValueError("Duplicate start offset")
        starts.add(start)
    # Sort edits by start position
    sorted_edits = sorted(edits, key=lambda e: e[0])
    # Check for overlapping edits
    prev_end = -1
    for start, end, _ in sorted_edits:
        if start < prev_end:
            raise ValueError("Overlapping edits")
        prev_end = end
    # Apply edits to the original text
    result_parts = []
    last_end = 0
    for start, end, replacement in sorted_edits:
        result_parts.append(text[last_end:start])
        result_parts.append(str(replacement))
        last_end = end
    result_parts.append(text[last_end:])
    return ''.join(result_parts)

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    if after is None:
        filtered = items
    else:
        filtered = [item for item in items if item['id'] > after]
    filtered.sort(key=lambda x: x['id'])
    page = filtered[:limit]
    next_cursor = None
    if len(page) == limit and len(filtered) > limit:
        next_cursor = page[-1]['id']
    return page, next_cursor

def expression(text):
    i = 0
    n = len(text)

    def skip_spaces():
        nonlocal i
        while i < n and text[i].isspace():
            i += 1

    def parse_number():
        nonlocal i
        skip_spaces()
        if i < n and text[i].isdigit():
            start = i
            while i < n and text[i].isdigit():
                i += 1
            return int(text[start:i])
        else:
            raise ValueError("Invalid number")

    def parse_factor():
        nonlocal i
        skip_spaces()
        if i < n and text[i] == '(':
            i += 1
            val = parse_expression()
            skip_spaces()
            if i >= n or text[i] != ')':
                raise ValueError("Missing closing parenthesis")
            i += 1
            return val
        if i < n and text[i] == '+':
            i += 1
            val = parse_factor()
            return +val
        if i < n and text[i] == '-':
            i += 1
            val = parse_factor()
            return -val
        if i < n and text[i].isdigit():
            return parse_number()
        else:
            raise ValueError("Unexpected character")

    def parse_term():
        val = parse_factor()
        while True:
            skip_spaces()
            if i < n and text[i] == '*':
                i += 1
                rhs = parse_factor()
                val *= rhs
            else:
                break
        return val

    def parse_expression():
        val = parse_term()
        while True:
            skip_spaces()
            if i < n and (text[i] == '+' or text[i] == '-'):
                op = text[i]
                i += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    result = parse_expression()
    skip_spaces()
    if i != n:
        raise ValueError("Invalid syntax")
    return result

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments are not allowed")
    delays = []
    for i in range(attempts):
        delay = initial * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays

import csv
from io import StringIO
def csv_records(text):
    if not text:
        return []
    f = StringIO(text)
    reader = csv.reader(f)
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    result = []
    for i, row in enumerate(rows[1:], start=1):
        if len(row) != len(headers):
            raise ValueError(f"Row {i} has {len(row)} fields, expected {len(headers)}")
        result.append(dict(zip(headers, row)))
    return result

def version_sort(versions):
    def key_func(v):
        # Split into integer parts, ignoring empty strings if any
        parts = [int(x) for x in v.split('.') if x != '']
        # Remove trailing zero segments
        while parts and parts[-1] == 0:
            parts.pop()
        return parts
    # Python's sort is stable, so ties retain original order
    return sorted(versions, key=key_func)

def glob_match(pattern, text):
    p = 0  # pattern index
    t = 0  # text index
    star_idx = -1  # index of last '*' in pattern
    match_idx = -1  # index in text where '*' started matching
    while t < len(text):
        if p < len(pattern) and (pattern[p] == '?' or pattern[p] == text[t]):
            p += 1
            t += 1
        elif p < len(pattern) and pattern[p] == '*':
            star_idx = p
            match_idx = t
            p += 1  # consume '*'
        elif star_idx != -1:
            # backtrack: let '*' consume one more character
            p = star_idx + 1
            t = match_idx + 1
            match_idx += 1
        else:
            return False
    # consume remaining '*' in pattern
    while p < len(pattern) and pattern[p] == '*':
        p += 1
    return p == len(pattern)

def schedule(jobs):
    # Sort jobs by end time without mutating the original list
    sorted_jobs = sorted(jobs, key=lambda x: x[1])
    n = len(sorted_jobs)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        start, end, profit = sorted_jobs[i-1]
        # Binary search for the rightmost job that ends <= start
        lo, hi = 0, i-2
        best = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if sorted_jobs[mid][1] <= start:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if best != -1:
            current_profit = profit + dp[best+1]
        else:
            current_profit = profit
        dp[i] = max(dp[i-1], current_profit)
    return dp[n]

def memo_cycle(definitions, name):
    memo = {}
    stack = set()
    def compute(n):
        if n not in definitions:
            raise ValueError(f"Missing dependency: {n}")
        if n in memo:
            return memo[n]
        if n in stack:
            raise ValueError("Cycle detected")
        stack.add(n)
        val = definitions[n]
        if isinstance(val, int):
            result = val
        elif isinstance(val, list):
            result = 0
            for dep in val:
                result += compute(dep)  # each occurrence counts
        else:
            raise ValueError(f"Invalid definition for {n}")
        memo[n] = result
        stack.remove(n)
        return result
    return compute(name)
